input_script:
var boardRequest = input.query || input || {};
var boardProjects = Array.isArray(boardRequest.projects) ? boardRequest.projects : (boardRequest.projects ? [boardRequest.projects] : []);
var boardScopes = [];
for (var bs = 0; bs < boardProjects.length; bs++) {
  var bp = boardProjects[bs];
  if (!bp) continue;
  var bk = typeof bp === 'object' ? String(bp.jiraproject || '').trim() : '';
  var bn = typeof bp === 'string' ? bp.trim() : String(bp.projectname || '').trim();
  if (!bk && !bn) continue;
  boardScopes.push({project_key: bk, project_name: bn,
    board_id: typeof bp === 'object' ? String(bp.boardid || '').trim() : '',
    connection_id: String((typeof bp === 'object' && bp.connectionid) || boardRequest.connectionid || '').trim()});
}

var projects = Array.isArray(input.projects) ? input.projects : [];
var projectKeys = [];
for (var i = 0; i < projects.length; i++) {
  var p = projects[i];
  var key = p && typeof p === 'object' ? String(p.jiraproject || '').trim() : '';
  if (key && projectKeys.indexOf(key) < 0) projectKeys.push(key);
}
var hasIssueScope = projectKeys.length > 0 ? 1 : 0;
var repoNames = [];
var names = Array.isArray(input.name) ? input.name : [];
var owners = Array.isArray(input.owner) ? input.owner : [];
for (var ri = 0; ri < names.length; ri++) {
  if (owners[ri] && names[ri]) repoNames.push(owners[ri] + '/' + names[ri]);
}
var userwhitelist = Array.isArray(input.userwhitelist) ? input.userwhitelist : [];
({
  boardScopes: JSON.stringify(boardScopes),
  projectKeys: projectKeys.length ? projectKeys : ['__NONE__'],
  hasIssueScope: hasIssueScope,
  repoNames: repoNames.length ? repoNames : ['__NONE__'],
  from: input.from || 0,
  to: input.to || 0,
  userwhitelist: userwhitelist.length ? userwhitelist : ['__NONE__'],
  hasUserWhitelist: userwhitelist.length ? 1 : 0
})

output_script:
var totalIssuesRows = results.total_issues || [];
var linkedIssuesRows = results.linked_issues || [];
var totalPrsRows = results.total_prs || [];
var linkedPrsRows = results.linked_prs || [];

var totalIssues = totalIssuesRows.length > 0 ? totalIssuesRows[0].total_issues : 0;
var linkedIssues = linkedIssuesRows.length > 0 ? linkedIssuesRows[0].linked_issues : 0;
var totalPrs = totalPrsRows.length > 0 ? totalPrsRows[0].total_prs : 0;
var linkedPrs = linkedPrsRows.length > 0 ? linkedPrsRows[0].linked_prs : 0;

var jiraToPrPct = totalIssues > 0 ? Math.round((linkedIssues / totalIssues) * 1000) / 10 : 0;
var prToJiraPct = totalPrs > 0 ? Math.round((linkedPrs / totalPrs) * 1000) / 10 : 0;

({
  type: "stats",
  label: "Jira to PR Traceability",
  description: "Shows how many resolved Jira tickets have a connected GitHub pull request, and vice versa. Connections are detected via manual PR links in Jira and Jira keys in PR titles.",
  data: {
    metrics: [
      { label: "Jira Tickets with Linked PRs", value: linkedIssues + " / " + totalIssues + " (" + jiraToPrPct + "%)" },
      { label: "PRs with Linked Jira Ticket", value: linkedPrs + " / " + totalPrs + " (" + prToJiraPct + "%)" }
    ]
  }
})
